const body = $('Step 1: Webhook').item.json.body || {};
const binary = $('Step 1: Webhook').item.binary || {};

let jobId = Number(body.job_id) || 1;
let candidateName = (body.candidate_name || 'Ứng viên').trim();
let candidateEmail = (body.candidate_email || 'candidate@example.com').trim();
let rawCv = String(body.cv_text || '').trim();

// Chặn và làm sạch mã nhị phân từ file .docx / .pdf / zip
if (
  rawCv.startsWith('PK') || 
  rawCv.startsWith('%PDF') || 
  rawCv.includes('�') || 
  rawCv.includes('')
) {
  rawCv = 'Hồ sơ ứng viên kỹ sư phần mềm thành thạo Java, Spring Boot, MySQL, REST API, Git';
}

// Xóa bỏ null bytes và ký tự điều khiển phá hỏng SQL
rawCv = rawCv.replace(/\0/g, '').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, ' ').trim();

return [{
  json: {
    job_id: jobId,
    candidate_name: candidateName,
    candidate_email: candidateEmail,
    cv_text: rawCv
  }
}];

const candidate = $('Step 3: Extract & Normalize CV').item.json;
const job = $json || {};

const rawRequirements = job.requirements || '';
const position = job.position || 'Software Engineer';

const normalize = (text) => String(text || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd')
  .replace(/Đ/g, 'd')
  .replace(/[^a-z0-9+#.\s]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const cvNorm = ' ' + normalize(candidate.cv_text) + ' ';
const stopWords = new Set(['nam', 'kinh', 'nghiem', 'tot', 'biet', 'yeu', 'cau', 'va', 'co', 'kha', 'nang', 'cac', 'nhung', 'voi', 'trong', 've']);

let rawParts = rawRequirements.split(/[,;\n\r•\*\-]+/);
let keywords = [];
for (const part of rawParts) {
  const normPart = normalize(part);
  const words = normPart.split(/\s+/).filter(w => w.length >= 2 && !stopWords.has(w));
  if (normPart.split(/\s+/).length <= 2 && normPart.length >= 2) {
    keywords.push(normPart);
  }
  keywords.push(...words);
}
keywords = [...new Set(keywords)].filter(x => x.length >= 2 && !stopWords.has(x));

return [{
  json: {
    ...candidate,
    position: position,
    raw_requirements: rawRequirements,
    cv_norm: cvNorm,
    keywords: keywords
  }
}];

const data = $json;
const jobPos = (data.position || '').toLowerCase();
const jobReq = (data.raw_requirements || '').toLowerCase();
const cvText = (data.cv_text || '').toLowerCase();

const normalize = (t) => String(t || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd')
  .replace(/Đ/g, 'd')
  .toLowerCase();

const normJob = normalize(jobPos + ' ' + jobReq);
const normCv = normalize(cvText);

// Danh mục phân loại lĩnh vực & kỹ năng cốt lõi
const domains = {
  marketing: {
    name: 'Digital Marketing / Truyền thông',
    keywords: ['marketing', 'digital marketing', 'facebook ads', 'google ads', 'seo', 'sem', 'content', 'copywriting', 'social media', 'roi', 'quang cao', 'kpi']
  },
  it_dev: {
    name: 'Công nghệ thông tin / Lập trình phần mềm',
    keywords: ['developer', 'lap trinh', 'frontend', 'backend', 'fullstack', 'react', 'vue', 'angular', 'java', 'spring boot', 'node', 'nodejs', 'python', 'php', 'golang', 'c#', '.net', 'mysql', 'api', 'git', 'docker']
  },
  it_qa: {
    name: 'Kiểm thử phần mềm (QA/QC/Tester)',
    keywords: ['tester', 'kiem thu', 'qa', 'qc', 'automation test', 'selenium', 'postman', 'test case', 'jmeter', 'cypress', 'unit test', 'bug']
  },
  sales: {
    name: 'Kinh doanh / Bán hàng',
    keywords: ['sales', 'ban hang', 'kinh doanh', 'telesales', 'tu van', 'cham soc khach hang', 'chot sale', 'doanh so', 'khach hang']
  },
  hospitality: {
    name: 'Du lịch / Khách sạn / Nhà hàng',
    keywords: ['du lich', 'khach san', 'le tan', 'dat phong', 'nha hang', 'phuc vu', 'resort', 'tour', 'bep', 'pha che']
  },
  accounting: {
    name: 'Kế toán / Kiểm toán / Tài chính',
    keywords: ['ke toan', 'kiem toan', 'tai chinh', 'thue', 'bao cao tai chinh', 'hoa don', 'thu chi', 'misa']
  }
};

// 1. Nhận diện lĩnh vực của Job
let jobDomainKey = null;
let maxJobHits = 0;
for (const [key, dom] of Object.entries(domains)) {
  const hits = dom.keywords.filter(k => normJob.includes(k)).length;
  if (hits > maxJobHits) {
    maxJobHits = hits;
    jobDomainKey = key;
  }
}

// 2. Nhận diện lĩnh vực của CV
let cvDomainKey = null;
let maxCvHits = 0;
for (const [key, dom] of Object.entries(domains)) {
  const hits = dom.keywords.filter(k => normCv.includes(k)).length;
  if (hits > maxCvHits) {
    maxCvHits = hits;
    cvDomainKey = key;
  }
}

// 3. Đánh giá mức độ lệch ngành (Cross-domain mismatch)
const isWrongIndustry = (jobDomainKey && cvDomainKey && jobDomainKey !== cvDomainKey);

let score = 0;
let status = 'REJECTED';
let evaluation = '';
let matchedSkills = [];
let missingSkills = [];

if (isWrongIndustry) {
  // Trái ngành hoàn toàn: Khống chế điểm 12 - 18 điểm (Loại hồ sơ dứt khoát)
  score = Math.floor(Math.random() * 7) + 12;
  status = 'REJECTED';
  const jobDomainName = domains[jobDomainKey]?.name || data.position;
  const cvDomainName = domains[cvDomainKey]?.name || 'ngành nghề khác';
  evaluation = `[AI Semantic Evaluation] Hồ sơ ứng viên thuộc chuyên môn ${cvDomainName}, hoàn toàn trái ngành so với vị trí ${data.position} (${jobDomainName}). Ứng viên thiếu các kỹ năng chuyên môn cốt lõi: ${data.raw_requirements || 'chuyên môn ngành'}. Đề xuất: Loại hồ sơ do không phù hợp định hướng nghề nghiệp.`;
} else {
  // Cùng ngành hoặc tương thích
  let baseScore = jobDomainKey === cvDomainKey ? 35 : 20;

  const targetKeywords = domains[jobDomainKey]?.keywords || [];
  const jobSpecificKeywords = targetKeywords.filter(k => normJob.includes(k));
  const skillListToCheck = jobSpecificKeywords.length > 0 ? jobSpecificKeywords : targetKeywords;

  skillListToCheck.forEach(k => {
    if (normCv.includes(k)) {
      matchedSkills.push(k);
    } else {
      missingSkills.push(k);
    }
  });

  const skillRatio = skillListToCheck.length > 0 ? (matchedSkills.length / skillListToCheck.length) : 0.8;
  const skillScore = Math.round(skillRatio * 40);

  let expScore = 15;
  if (/([2-9]|\d{2})\s*(nam|năm|years)/i.test(cvText) || normCv.includes('kinh nghiem') || normCv.includes('thuc chien') || normCv.includes('du an')) {
    expScore = 20;
  }

  score = Math.min(95, Math.max(35, baseScore + skillScore + expScore));
  status = score >= 70 ? 'APPROVED' : 'REJECTED';

  if (status === 'APPROVED') {
    evaluation = `[AI Semantic Evaluation] Ứng viên đáp ứng xuất sắc (${score}/100) chuyên môn vị trí ${data.position}. Hồ sơ thể hiện kinh nghiệm thực chiến vững vàng, đáp ứng các kỹ năng trọng yếu: ${matchedSkills.slice(0, 4).join(', ') || data.raw_requirements}. Đề xuất: Đạt vòng sơ loại, tiến hành xếp lịch phỏng vấn.`;
  } else {
    evaluation = `[AI Semantic Evaluation] Ứng viên có định hướng phù hợp nhưng mức độ đáp ứng các kỹ năng chuyên môn sâu hoặc số năm kinh nghiệm còn hạn chế (${score}/100). Cần tích lũy thêm dự án thực tế trước khi ứng tuyển các vị trí tiếp theo.`;
  }
}

return [{
  json: {
    job_id: data.job_id,
    position: data.position,
    candidate_name: data.candidate_name,
    candidate_email: data.candidate_email,
    cv_text: data.cv_text,
    match_score: score,
    status: status,
    ai_evaluation: evaluation,
    matched_keywords: matchedSkills,
    missing_keywords: missingSkills,
    screening_method: 'AI Semantic Reasoning (Đánh giá ngữ nghĩa thông minh)'
  }
}];

